/**
 * Brand logos encoded as base64 Data URIs for offline, synchronous PDF rendering
 * and thermal printer receipts.
 */
export const CHIMERTECH_LOGO = 'data:image/png;base64,';

export const IHERD_LOGO = 'data:image/png;base64,';

/**
 * Combined monochrome 1-bit partner logos PNG for 58mm / 80mm thermal receipt slips.
 * Pure black pixels on transparent background to ensure 100% crisp direct-thermal burn.
 */
export const PARTNER_LOGOS_MONO_PNG = 'data:image/png;base64,';

/**
 * Pre-compiled ESC/POS raster bitmap command (GS v 0) for 58mm / 80mm thermal receipt printers.
 * 384 dots width x 64 dots height monochrome raster image.
 */
export const ESC_POS_PARTNER_LOGOS_B64 = '';

/**
 * Decodes the base64 ESC/POS raster bitmap into a Uint8Array byte buffer.
 */
export function getEscPosPartnerLogosBytes() {
  if (typeof atob === 'undefined') return new Uint8Array(0);
  const binaryString = atob(ESC_POS_PARTNER_LOGOS_B64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}
